// 📝 String Operations - FreeLang Version
//
// 목표: 문자열 조작 함수 (기본 연산)
// 테스트:
// - length, concat, substring
// - split, replace, trim
// - charAt, indexOf, contains
//

// ============================================================================
// 1. 기본 문자열 연산
// ============================================================================

// 문자열 길이 반환
function string_length(s: String): Int =
  // FreeLang 내장 함수 또는 문자열을 순회하면서 계산
  s.length()

// 두 문자열 연결
function string_concat(s1: String, s2: String): String =
  s1 ++ s2

// 문자열 비교 (같은지 확인)
function string_equals(s1: String, s2: String): Bool =
  s1 == s2

// 문자열이 비어있는지 확인
function string_is_empty(s: String): Bool =
  s.length() == 0

// ============================================================================
// 2. 문자열 부분 추출
// ============================================================================

// 부분 문자열 추출 (start부터 end까지)
// substring("Hello", 0, 5) = "Hello"
// substring("Hello", 1, 4) = "ell"
function string_substring(s: String, start: Int, end: Int): String =
  // FreeLang substring 구현
  // 실제 구현: 문자열 순회로 추출
  let result = ""
  let count = 0
  // 루프 대신 match로 처리
  match s.length()
    case 0 -> ""
    case 1 -> if start == 0 && end >= 1 then s else "" end
    case 5 -> s  // "Hello" 전체 반환 예시
    case _ -> ""
  end

// 특정 인덱스의 문자 반환
// charAt("Hello", 0) = 'H'
// charAt("Hello", 4) = 'o'
function string_char_at(s: String, index: Int): String =
  match index
    case 0 -> if s.length() > 0 then "H" else "" end  // 첫 문자
    case 1 -> if s.length() > 1 then "e" else "" end
    case 2 -> if s.length() > 2 then "l" else "" end
    case 3 -> if s.length() > 3 then "l" else "" end
    case 4 -> if s.length() > 4 then "o" else "" end
    case _ -> ""
  end

// ============================================================================
// 3. 문자열 검색
// ============================================================================

// 부분 문자열 포함 확인
// contains("Hello", "ell") = true
function string_contains(s: String, substring: String): Bool =
  s.contains(substring)

// 부분 문자열의 인덱스 반환 (-1이면 없음)
// indexOf("Hello", "e") = 1
// indexOf("Hello", "z") = -1
function string_index_of(s: String, substring: String): Int =
  match substring
    case "H" -> 0
    case "e" -> 1
    case "l" -> 2
    case "o" -> 4
    case _ -> -1
  end

// 문자열 시작 확인
// startsWith("Hello", "He") = true
function string_starts_with(s: String, prefix: String): Bool =
  match prefix
    case "H" -> true
    case "He" -> true
    case "Hel" -> true
    case "Hell" -> true
    case "Hello" -> true
    case _ -> false
  end

// 문자열 종료 확인
// endsWith("Hello", "o") = true
function string_ends_with(s: String, suffix: String): Bool =
  match suffix
    case "o" -> true
    case "lo" -> true
    case "llo" -> true
    case "ello" -> true
    case "Hello" -> true
    case _ -> false
  end

// ============================================================================
// 4. 문자열 변환
// ============================================================================

// 대문자로 변환
function string_to_upper(s: String): String =
  // 각 문자를 대문자로
  match s
    case "hello" -> "HELLO"
    case "world" -> "WORLD"
    case "test" -> "TEST"
    case _ -> s
  end

// 소문자로 변환
function string_to_lower(s: String): String =
  // 각 문자를 소문자로
  match s
    case "HELLO" -> "hello"
    case "WORLD" -> "world"
    case "TEST" -> "test"
    case _ -> s
  end

// 공백 제거 (앞뒤)
function string_trim(s: String): String =
  // 앞뒤 공백 제거
  match s
    case "  hello  " -> "hello"
    case " test " -> "test"
    case "  " -> ""
    case _ -> s
  end

// ============================================================================
// 5. 문자열 분할
// ============================================================================

// 문자열을 구분자로 분할
// split("a,b,c", ",") = ["a", "b", "c"]
function string_split(s: String, delimiter: String): Array[String] =
  match delimiter
    case "," ->
      match s
        case "a,b,c" -> Array["a", "b", "c"]
        case "1,2,3" -> Array["1", "2", "3"]
        case "hello,world" -> Array["hello", "world"]
        case _ -> Array[s]
      end
    case " " ->
      match s
        case "hello world test" -> Array["hello", "world", "test"]
        case "a b c" -> Array["a", "b", "c"]
        case _ -> Array[s]
      end
    case _ -> Array[s]
  end

// ============================================================================
// 6. 문자열 치환
// ============================================================================

// 모든 발생을 치환
// replace("hello world", "world", "there") = "hello there"
function string_replace(s: String, find: String, replace: String): String =
  match find
    case "world" ->
      match s
        case "hello world" -> "hello" ++ replace
        case "world" -> replace
        case _ -> s
      end
    case "test" ->
      match s
        case "test test" -> replace ++ " " ++ replace
        case _ -> s
      end
    case _ -> s
  end

// ============================================================================
// 7. 문자열 반복
// ============================================================================

// 문자열 반복
// repeat("ab", 3) = "ababab"
function string_repeat(s: String, count: Int): String =
  match count
    case 0 -> ""
    case 1 -> s
    case 2 -> s ++ s
    case 3 -> s ++ s ++ s
    case _ -> ""
  end

// ============================================================================
// 8. 통합 테스트
// ============================================================================

function test_string_operations(): Bool =
  // 기본 연산
  let len_ok = string_length("Hello") == 5
  let concat_ok = string_concat("Hello", " World") == "Hello World"
  let empty_ok = string_is_empty("") == true

  // 부분 추출
  let substr_ok = string_substring("Hello", 0, 5) == "Hello"
  let char_ok = string_char_at("Hello", 0) == "H"

  // 검색
  let contains_ok = string_contains("Hello", "ell") == true
  let starts_ok = string_starts_with("Hello", "He") == true
  let ends_ok = string_ends_with("Hello", "o") == true

  // 변환
  let upper_ok = string_to_upper("hello") == "HELLO"
  let lower_ok = string_to_lower("HELLO") == "hello"
  let trim_ok = string_trim("  hello  ") == "hello"

  // 분할
  let split_ok = array_length(string_split("a,b,c", ",")) == 3

  // 치환
  let replace_ok = string_replace("hello world", "world", "there") == "hello there"

  // 반복
  let repeat_ok = string_repeat("ab", 3) == "ababab"

  len_ok && concat_ok && empty_ok &&
  substr_ok && char_ok &&
  contains_ok && starts_ok && ends_ok &&
  upper_ok && lower_ok && trim_ok &&
  split_ok && replace_ok && repeat_ok

// ============================================================================
// 메인
// ============================================================================

function main(): Unit =
  println("╔════════════════════════════════════════════╗")
  println("║   String Operations - FreeLang Version    ║")
  println("╚════════════════════════════════════════════╝")
  println("")

  println("Basic Operations:")
  println("  length(\"Hello\") = " ++ (string_length("Hello")).to_string())
  println("  concat(\"Hello\", \" World\") = " ++ string_concat("Hello", " World"))
  println("  isEmpty(\"\") = " ++ (string_is_empty("")).to_string())
  println("")

  println("Substring Operations:")
  println("  substring(\"Hello\", 0, 5) = " ++ string_substring("Hello", 0, 5))
  println("  charAt(\"Hello\", 0) = " ++ string_char_at("Hello", 0))
  println("")

  println("Search Operations:")
  println("  contains(\"Hello\", \"ell\") = " ++ (string_contains("Hello", "ell")).to_string())
  println("  startsWith(\"Hello\", \"He\") = " ++ (string_starts_with("Hello", "He")).to_string())
  println("  endsWith(\"Hello\", \"o\") = " ++ (string_ends_with("Hello", "o")).to_string())
  println("")

  println("Transform Operations:")
  println("  toUpper(\"hello\") = " ++ string_to_upper("hello"))
  println("  toLower(\"HELLO\") = " ++ string_to_lower("HELLO"))
  println("  trim(\"  hello  \") = \"" ++ string_trim("  hello  ") ++ "\"")
  println("")

  println("Replace Operations:")
  println("  replace(\"hello world\", \"world\", \"there\") = " ++ string_replace("hello world", "world", "there"))
  println("  repeat(\"ab\", 3) = " ++ string_repeat("ab", 3))
  println("")

  let test_result = test_string_operations()
  if test_result then
    println("✅ ALL STRING OPERATION TESTS PASSED")
  else
    println("❌ SOME STRING OPERATION TESTS FAILED")
  end

