// 📊 Array/Collection Operations - Go Version
//
// 목표: Go의 슬라이스, 맵, 고차함수 검증
// 특징: 내장 고차함수, 표준 라이브러리 활용

package main

import (
	"fmt"
	"sort"
)

// ============================================================================
// 1. 기본 배열 연산
// ============================================================================

func arrayLength(arr []int) int {
	return len(arr)
}

func arrayGet(arr []int, index int) (int, bool) {
	if index >= 0 && index < len(arr) {
		return arr[index], true
	}
	return 0, false
}

func arraySet(arr []int, index int, value int) ([]int, bool) {
	if index >= 0 && index < len(arr) {
		arr[index] = value
		return arr, true
	}
	return arr, false
}

func arrayPush(arr []int, value int) []int {
	return append(arr, value)
}

func arrayPop(arr []int) ([]int, int, bool) {
	if len(arr) > 0 {
		last := arr[len(arr)-1]
		return arr[:len(arr)-1], last, true
	}
	return arr, 0, false
}

// ============================================================================
// 2. 고차함수: map
// ============================================================================

func arrayMap(arr []int, f func(int) int) []int {
	result := make([]int, len(arr))
	for i, v := range arr {
		result[i] = f(v)
	}
	return result
}

func arrayMapDouble(arr []int) []int {
	return arrayMap(arr, func(x int) int { return x * 2 })
}

func arrayMapSquare(arr []int) []int {
	return arrayMap(arr, func(x int) int { return x * x })
}

// ============================================================================
// 3. 고차함수: filter
// ============================================================================

func arrayFilter(arr []int, predicate func(int) bool) []int {
	var result []int
	for _, v := range arr {
		if predicate(v) {
			result = append(result, v)
		}
	}
	return result
}

func arrayFilterEven(arr []int) []int {
	return arrayFilter(arr, func(x int) bool { return x%2 == 0 })
}

func arrayFilterPositive(arr []int) []int {
	return arrayFilter(arr, func(x int) bool { return x > 0 })
}

// ============================================================================
// 4. 고차함수: fold (reduce)
// ============================================================================

func arrayFold(arr []int, init int, f func(int, int) int) int {
	acc := init
	for _, v := range arr {
		acc = f(acc, v)
	}
	return acc
}

func arraySum(arr []int) int {
	return arrayFold(arr, 0, func(acc, v int) int { return acc + v })
}

func arrayProduct(arr []int) int {
	return arrayFold(arr, 1, func(acc, v int) int { return acc * v })
}

func arrayMax(arr []int) (int, bool) {
	if len(arr) == 0 {
		return 0, false
	}
	max := arr[0]
	for _, v := range arr {
		if v > max {
			max = v
		}
	}
	return max, true
}

func arrayMin(arr []int) (int, bool) {
	if len(arr) == 0 {
		return 0, false
	}
	min := arr[0]
	for _, v := range arr {
		if v < min {
			min = v
		}
	}
	return min, true
}

// ============================================================================
// 5. 기본 배열 변환
// ============================================================================

func arrayReverse(arr []int) []int {
	result := make([]int, len(arr))
	for i, v := range arr {
		result[len(arr)-1-i] = v
	}
	return result
}

func arrayFlatten(arr [][]int) []int {
	var result []int
	for _, subArr := range arr {
		result = append(result, subArr...)
	}
	return result
}

func arrayUnique(arr []int) []int {
	m := make(map[int]bool)
	var result []int
	for _, v := range arr {
		if !m[v] {
			m[v] = true
			result = append(result, v)
		}
	}
	return result
}

// ============================================================================
// 6. 배열 검색
// ============================================================================

func arrayContains(arr []int, value int) bool {
	for _, v := range arr {
		if v == value {
			return true
		}
	}
	return false
}

func arrayIndexOf(arr []int, value int) (int, bool) {
	for i, v := range arr {
		if v == value {
			return i, true
		}
	}
	return -1, false
}

func arrayFind(arr []int, predicate func(int) bool) (int, bool) {
	for _, v := range arr {
		if predicate(v) {
			return v, true
		}
	}
	return 0, false
}

// ============================================================================
// 7. 배열 정렬
// ============================================================================

func arraySort(arr []int) []int {
	result := make([]int, len(arr))
	copy(result, arr)
	sort.Ints(result)
	return result
}

// ============================================================================
// 8. 딕셔너리 (Go의 map)
// ============================================================================

func dictCreate() map[string]int {
	return make(map[string]int)
}

func dictSet(dict map[string]int, key string, value int) map[string]int {
	dict[key] = value
	return dict
}

func dictGet(dict map[string]int, key string) (int, bool) {
	v, ok := dict[key]
	return v, ok
}

func dictRemove(dict map[string]int, key string) map[string]int {
	delete(dict, key)
	return dict
}

func dictKeys(dict map[string]int) []string {
	var keys []string
	for k := range dict {
		keys = append(keys, k)
	}
	return keys
}

func dictValues(dict map[string]int) []int {
	var values []int
	for _, v := range dict {
		values = append(values, v)
	}
	return values
}

// ============================================================================
// 9. 집합 (Set)
// ============================================================================

type SetOps struct {
	elements map[int]bool
}

func setCreate(arr []int) *SetOps {
	s := &SetOps{elements: make(map[int]bool)}
	for _, v := range arr {
		s.elements[v] = true
	}
	return s
}

func setContains(s *SetOps, value int) bool {
	_, ok := s.elements[value]
	return ok
}

func setAdd(s *SetOps, value int) *SetOps {
	s.elements[value] = true
	return s
}

func setRemove(s *SetOps, value int) *SetOps {
	delete(s.elements, value)
	return s
}

func setUnion(s1, s2 *SetOps) *SetOps {
	result := &SetOps{elements: make(map[int]bool)}
	for k := range s1.elements {
		result.elements[k] = true
	}
	for k := range s2.elements {
		result.elements[k] = true
	}
	return result
}

func setIntersection(s1, s2 *SetOps) *SetOps {
	result := &SetOps{elements: make(map[int]bool)}
	for k := range s1.elements {
		if _, ok := s2.elements[k]; ok {
			result.elements[k] = true
		}
	}
	return result
}

func setSize(s *SetOps) int {
	return len(s.elements)
}

// ============================================================================
// 10. 통합 테스트
// ============================================================================

func testArrayOperations() bool {
	arr := []int{1, 2, 3, 4, 5}

	// 기본 연산
	lenOk := arrayLength(arr) == 5
	v, getOk := arrayGet(arr, 0)
	getOk = getOk && v == 1

	// map
	doubled := arrayMapDouble(arr)
	mapOk := arrayLength(doubled) == 5

	// filter
	evens := arrayFilterEven(arr)
	filterOk := arrayLength(evens) == 2

	// fold
	sumOk := arraySum(arr) == 15
	productOk := arrayProduct(arr) == 120

	// 검색
	containsOk := arrayContains(arr, 3)
	v, findOk := arrayFind(arr, func(x int) bool { return x > 3 })
	findOk = findOk && v >= 4

	return lenOk && getOk && mapOk && filterOk && sumOk && productOk && containsOk && findOk
}

func main() {
	fmt.Println("╔════════════════════════════════════════════╗")
	fmt.Println("║  Array Operations - Go Version            ║")
	fmt.Println("╚════════════════════════════════════════════╝")
	fmt.Println("")

	arr := []int{1, 2, 3, 4, 5}

	fmt.Println("Basic Operations:")
	fmt.Printf("  length([1,2,3,4,5]) = %d\n", arrayLength(arr))
	v, _ := arrayGet(arr, 0)
	fmt.Printf("  get([1,2,3,4,5], 0) = %d\n", v)
	fmt.Println("")

	fmt.Println("Higher-Order Functions:")
	doubled := arrayMapDouble(arr)
	fmt.Printf("  map(double, [1,2,3,4,5]) length = %d\n", arrayLength(doubled))

	evens := arrayFilterEven(arr)
	fmt.Printf("  filter(even, [1,2,3,4,5]) length = %d\n", arrayLength(evens))

	fmt.Printf("  sum([1,2,3,4,5]) = %d\n", arraySum(arr))
	fmt.Printf("  product([1,2,3,4,5]) = %d\n", arrayProduct(arr))
	fmt.Println("")

	fmt.Println("Search Operations:")
	fmt.Printf("  contains([1,2,3,4,5], 3) = %v\n", arrayContains(arr, 3))
	idx, _ := arrayIndexOf(arr, 3)
	fmt.Printf("  indexOf([1,2,3,4,5], 3) = %d\n", idx)
	fmt.Println("")

	fmt.Println("Dictionary Operations:")
	dict := dictCreate()
	dict = dictSet(dict, "a", 10)
	dict = dictSet(dict, "b", 20)
	v, _ := dictGet(dict, "a")
	fmt.Printf("  dict[\"a\"] = %d\n", v)
	fmt.Println("")

	fmt.Println("Set Operations:")
	s1 := setCreate([]int{1, 2, 3})
	s2 := setCreate([]int{2, 3, 4})
	union := setUnion(s1, s2)
	fmt.Printf("  union({1,2,3}, {2,3,4}) size = %d\n", setSize(union))
	fmt.Println("")

	testResult := testArrayOperations()
	if testResult {
		fmt.Println("✅ ALL ARRAY OPERATION TESTS PASSED")
	} else {
		fmt.Println("❌ SOME ARRAY OPERATION TESTS FAILED")
	}
}

