func arrayMax(arr []int) (int, bool) {
	if len(arr) == 0 {
		return 0, false
	}
	max := arr[0]
	for _, v := range arr {
		if v > max {
			max = v
		}
	}
	return max, true
}

func arrayMin(arr []int) (int, bool) {
	if len(arr) == 0 {
		return 0, false
	}
	min := arr[0]
	for _, v := range arr {
		if v < min {
			min = v
		}
	}
	return min, true
}

