	printf("  filter(even, [1,2,3,4,5]) length = %d\n", array_length(evens));

	printf("  sum([1,2,3,4,5]) = %d\n", array_sum(arr));
	printf("  product([1,2,3,4,5]) = %d\n", array_product(arr));
	printf("\n");

	printf("Search Operations:\n");
