	if (dict_get(dict, "a", &v)) {
		printf("  dict[\"a\"] = %d\n", v);
	}
	printf("\n");

	printf("Set Operations:\n");
	Set *s1 = set_create(arr);
	DynamicArray *arr2 = array_create(3);
