bool is_even(int x) { return x % 2 == 0; }
bool is_positive(int x) { return x > 0; }

DynamicArray *array_filter_even(DynamicArray *arr) {
	return array_filter(arr, is_even);
}

DynamicArray *array_filter_positive(DynamicArray *arr) {
	return array_filter(arr, is_positive);
}

// ============================================================================
// 4. 고차함수: fold (reduce)
// ============================================================================

typedef int (*FoldFunction)(int, int);

int array_fold(DynamicArray *arr, int init, FoldFunction f) {
	int acc = init;

	for (int i = 0; i < arr->size; i++) {
		acc = f(acc, arr->data[i]);
	}

	return acc;
}

int add_fn(int a, int b) { return a + b; }
int mul_fn(int a, int b) { return a * b; }
int max_fn(int a, int b) { return a > b ? a : b; }

int array_sum(DynamicArray *arr) {
	return array_fold(arr, 0, add_fn);
}

int array_product(DynamicArray *arr) {
	return array_fold(arr, 1, mul_fn);
}

bool array_max(DynamicArray *arr, int *out_max) {
	if (!arr || arr->size == 0) return false;

	*out_max = array_fold(arr, arr->data[0], max_fn);
	return true;
}

// ============================================================================
// 5. 기본 배열 변환
// ============================================================================

DynamicArray *array_reverse(DynamicArray *arr) {
	DynamicArray *result = array_create(arr->size);

	for (int i = arr->size - 1; i >= 0; i--) {
		array_push(result, arr->data[i]);
	}

	return result;
}

DynamicArray *array_flatten(DynamicArray **arrays, int array_count) {
	DynamicArray *result = array_create(100);

	for (int i = 0; i < array_count; i++) {
		DynamicArray *arr = arrays[i];
		for (int j = 0; j < arr->size; j++) {
			array_push(result, arr->data[j]);
		}
	}

	return result;
}

DynamicArray *array_unique(DynamicArray *arr) {
	DynamicArray *result = array_create(arr->size);

	for (int i = 0; i < arr->size; i++) {
		bool found = false;
		for (int j = 0; j < result->size; j++) {
			if (result->data[j] == arr->data[i]) {
				found = true;
				break;
			}
		}

		if (!found) {
			array_push(result, arr->data[i]);
		}
	}

	return result;
}

// ============================================================================
// 6. 배열 검색
// ============================================================================

bool array_contains(DynamicArray *arr, int value) {
	for (int i = 0; i < arr->size; i++) {
		if (arr->data[i] == value) return true;
	}
	return false;
}

bool array_index_of(DynamicArray *arr, int value, int *out_index) {
	for (int i = 0; i < arr->size; i++) {
		if (arr->data[i] == value) {
			*out_index = i;
			return true;
		}
	}
	return false;
}

bool array_find(DynamicArray *arr, BoolFunction predicate, int *out_value) {
	for (int i = 0; i < arr->size; i++) {
		if (predicate(arr->data[i])) {
			*out_value = arr->data[i];
			return true;
		}
	}
	return false;
}

// ============================================================================
// 7. 배열 정렬
// ============================================================================

int compare_ints(const void *a, const void *b) {
	return *(int *)a - *(int *)b;
}

DynamicArray *array_sort(DynamicArray *arr) {
	DynamicArray *result = array_create(arr->size);
	result->size = arr->size;

	memcpy(result->data, arr->data, sizeof(int) * arr->size);
	qsort(result->data, result->size, sizeof(int), compare_ints);

	return result;
}

// ============================================================================
// 8. 딕셔너리 (해시 테이블)
// ============================================================================

typedef struct {
	char *key;
	int value;
} DictEntry;

typedef struct {
	DictEntry *entries;
	int size;
	int capacity;
} Dictionary;

Dictionary *dict_create(int capacity) {
	Dictionary *dict = (Dictionary *)malloc(sizeof(Dictionary));
	dict->entries = (DictEntry *)malloc(sizeof(DictEntry) * capacity);
	dict->size = 0;
	dict->capacity = capacity;
	return dict;
}

void dict_destroy(Dictionary *dict) {
	if (dict) {
		for (int i = 0; i < dict->size; i++) {
			free(dict->entries[i].key);
		}
		free(dict->entries);
		free(dict);
	}
}

void dict_set(Dictionary *dict, const char *key, int value) {
	for (int i = 0; i < dict->size; i++) {
		if (strcmp(dict->entries[i].key, key) == 0) {
			dict->entries[i].value = value;
			return;
		}
	}

	if (dict->size >= dict->capacity) {
		dict->capacity *= 2;
		dict->entries = (DictEntry *)realloc(dict->entries, sizeof(DictEntry) * dict->capacity);
	}

	dict->entries[dict->size].key = (char *)malloc(strlen(key) + 1);
	strcpy(dict->entries[dict->size].key, key);
	dict->entries[dict->size].value = value;
	dict->size++;
}

bool dict_get(Dictionary *dict, const char *key, int *out_value) {
	for (int i = 0; i < dict->size; i++) {
		if (strcmp(dict->entries[i].key, key) == 0) {
			*out_value = dict->entries[i].value;
			return true;
		}
	}
	return false;
}

// ============================================================================
// 9. 집합 (Set)
// ============================================================================

typedef DynamicArray Set;

Set *set_create(DynamicArray *arr) {
	return array_unique(arr);
}

bool set_contains(Set *s, int value) {
	return array_contains(s, value);
}

void set_add(Set *s, int value) {
	if (!array_contains(s, value)) {
		array_push(s, value);
	}
}

Set *set_union(Set *s1, Set *s2) {
	Set *result = array_create(s1->size + s2->size);

	for (int i = 0; i < s1->size; i++) {
		array_push(result, s1->data[i]);
	}

	for (int i = 0; i < s2->size; i++) {
		if (!array_contains(result, s2->data[i])) {
			array_push(result, s2->data[i]);
		}
	}

	return result;
}

Set *set_intersection(Set *s1, Set *s2) {
	Set *result = array_create(s1->size < s2->size ? s1->size : s2->size);

	for (int i = 0; i < s1->size; i++) {
		if (array_contains(s2, s1->data[i])) {
			array_push(result, s1->data[i]);
		}
	}

	return result;
}

// ============================================================================
// 10. 통합 테스트
// ============================================================================

bool test_array_operations() {
