// ============================================================================

typedef struct {
	char *expression;
	double result;
	char *operation;
	int success;
	char *error_message;
} CalculationResult;

typedef struct {
	CalculationResult *history;
	int history_size;
	double last_result;
	double memory;
	int precision;
} CalculatorState;

// ============================================================================
// 2. 기본 산술 연산
// ============================================================================

double add(double a, double b) {
	return a + b;
}

double subtract(double a, double b) {
	return a - b;
}

double multiply(double a, double b) {
	return a * b;
}

double divide_safe(double a, double b, int *error) {
	if (b == 0.0) {
		*error = 1;
		return 0.0;
	}
	return a / b;
}

int modulo_safe(int a, int b, int *error) {
	if (b == 0) {
		*error = 1;
		return 0;
	}
	return a % b;
}

// ============================================================================
// 3. 고급 연산
// ============================================================================

double power_func(double base, int exponent) {
	return pow(base, (double)exponent);
}

int factorial_safe(int n, int *error) {
	if (n < 0) {
		*error = 1;
		return 0;
	}
	int result = 1;
	for (int i = 1; i <= n; i++) {
		result *= i;
	}
	return result;
}

double absolute_val(double x) {
	return fabs(x);
}

double square_root_safe(double x, int *error) {
	if (x < 0.0) {
		*error = 1;
		return 0.0;
	}
	return sqrt(x);
}

// ============================================================================
// 4. 통계 연산
// ============================================================================

double sum_array(double *arr, int size) {
	double sum = 0.0;
	for (int i = 0; i < size; i++) {
		sum += arr[i];
	}
	return sum;
}

double average_safe(double *arr, int size, int *error) {
	if (size == 0) {
		*error = 1;
		return 0.0;
	}
	return sum_array(arr, size) / size;
}

double max_array_safe(double *arr, int size, int *error) {
	if (size == 0) {
		*error = 1;
		return 0.0;
	}
	double max = arr[0];
	for (int i = 1; i < size; i++) {
		if (arr[i] > max) {
			max = arr[i];
		}
	}
	return max;
}

double min_array_safe(double *arr, int size, int *error) {
	if (size == 0) {
		*error = 1;
		return 0.0;
	}
	double min = arr[0];
	for (int i = 1; i < size; i++) {
		if (arr[i] < min) {
			min = arr[i];
		}
	}
	return min;
}

double variance_safe(double *arr, int size, int *error) {
	double avg = average_safe(arr, size, error);
	if (*error) return 0.0;

	double sum_sq = 0.0;
	for (int i = 0; i < size; i++) {
		double diff = arr[i] - avg;
		sum_sq += diff * diff;
	}
	return sum_sq / size;
}

double standard_deviation_safe(double *arr, int size, int *error) {
	double var = variance_safe(arr, size, error);
	if (*error) return 0.0;
	return sqrt(var);
}

