// ============================================================================

double celsius_to_fahrenheit(double celsius) {
	return celsius * 9.0 / 5.0 + 32.0;
}

double fahrenheit_to_celsius(double fahrenheit) {
	return (fahrenheit - 32.0) * 5.0 / 9.0;
}

double kilometers_to_miles(double km) {
	return km * 0.621371;
}

double miles_to_kilometers(double miles) {
	return miles * 1.60934;
}

double kilograms_to_pounds(double kg) {
	return kg * 2.20462;
}

double pounds_to_kilograms(double lb) {
	return lb / 2.20462;
}

// ============================================================================
// 6. 계산기 상태 관리
// ============================================================================

CalculatorState *create_calculator() {
	CalculatorState *calc = (CalculatorState *)malloc(sizeof(CalculatorState));
	calc->history = (CalculationResult *)malloc(100 * sizeof(CalculationResult));
	calc->history_size = 0;
	calc->last_result = 0.0;
	calc->memory = 0.0;
	calc->precision = 4;
	return calc;
}

void destroy_calculator(CalculatorState *calc) {
	if (calc) {
		free(calc->history);
		free(calc);
	}
}

void calculator_memory_add(CalculatorState *calc, double value) {
	calc->memory += value;
}

double calculator_memory_recall(CalculatorState *calc) {
	return calc->memory;
}

void calculator_memory_clear(CalculatorState *calc) {
	calc->memory = 0.0;
}

