// Provides hover information (type hints, documentation) for symbols
// ============================================================================

// HoverProvider provides hover information
type HoverProvider struct {
	source string
	lines  []string
}

// NewHoverProvider creates a new hover provider
func NewHoverProvider(source string) *HoverProvider {
	return &HoverProvider{
		source: source,
		lines:  splitLines(source),
	}
}

// ProvideAt provides hover information at given position
func (hp *HoverProvider) ProvideAt(pos Position) *Hover {
	if pos.Line >= len(hp.lines) {
		return nil
	}

	line := hp.lines[pos.Line]
	if pos.Character > len(line) {
		return nil
	}

	// Extract word at position
	word := hp.extractWord(line, pos.Character)
	if word == "" {
		return nil
	}

	// Find definition and type
	def := hp.findDefinition(word, pos.Line)
	if def == "" {
		// Try built-in
		def = hp.getBuiltInDocumentation(word)
	}

	if def == "" {
		return nil
	}

	// Find word range
	startChar := pos.Character
	for startChar > 0 && isWordChar(rune(line[startChar-1])) {
		startChar--
	}

	return &Hover{
		Contents: def,
		Range: &Range{
			Start: Position{Line: pos.Line, Character: startChar},
			End:   Position{Line: pos.Line, Character: pos.Character},
		},
	}
}

// ============================================================================
// Definition Finding
// ============================================================================

// findDefinition finds the definition of a symbol
func (hp *HoverProvider) findDefinition(symbol string, currentLine int) string {
	// Search backwards for definition
	for i := currentLine; i >= 0; i-- {
		line := hp.lines[i]

		// Variable definition
		if strings.Contains(line, "let "+symbol) {
			return hp.formatVariableInfo(line, symbol)
		}

		// Function definition
		if strings.Contains(line, "function "+symbol) {
			return hp.formatFunctionInfo(line, symbol)
		}
	}

	return ""
}

// formatVariableInfo formats variable information
func (hp *HoverProvider) formatVariableInfo(line, name string) string {
	line = strings.TrimSpace(line)

	// Extract type annotation
	var typ string
	if idx := strings.Index(line, ":"); idx >= 0 {
		eqIdx := strings.Index(line, "=")
		if eqIdx < 0 {
			eqIdx = len(line)
		}
		typ = strings.TrimSpace(line[idx+1 : eqIdx])
	}

	// Extract initialization value
	var value string
	if idx := strings.Index(line, "="); idx >= 0 {
		value = strings.TrimSpace(line[idx+1:])
	}

	var info strings.Builder
	info.WriteString(fmt.Sprintf("`let %s", name))
	if typ != "" {
		info.WriteString(fmt.Sprintf(": %s", typ))
	}
	if value != "" {
		info.WriteString(fmt.Sprintf(" = %s`", value))
	} else {
		info.WriteString("`")
	}
	info.WriteString("\n\n")

	// Add type information
	if typ != "" {
		info.WriteString(fmt.Sprintf("**Type**: %s\n\n", typ))
	}

	// Add brief description
	info.WriteString(fmt.Sprintf("Variable `%s`", name))
	if value != "" {
		info.WriteString(fmt.Sprintf(" initialized to `%s`", value))
	}

	return info.String()
}

// formatFunctionInfo formats function information
func (hp *HoverProvider) formatFunctionInfo(line, name string) string {
	line = strings.TrimSpace(line)

	// Extract function signature
	sig := hp.extractFunctionSignature(line)

	var info strings.Builder
	info.WriteString(fmt.Sprintf("`%s`\n\n", sig))

	// Extract and document parameters
	params := hp.extractParameters(line)
	if len(params) > 0 {
		info.WriteString("**Parameters**:\n\n")
		for _, param := range params {
			info.WriteString(fmt.Sprintf("- `%s`: %s\n", param.Name, param.Type))
		}
		info.WriteString("\n")
	}

	// Extract return type
	returnType := hp.extractReturnType(line)
	if returnType != "" {
		info.WriteString(fmt.Sprintf("**Returns**: %s\n\n", returnType))
	}

	// Add complexity info if available
	complexity := hp.analyzeComplexity(line)
	if complexity != "" {
		info.WriteString(fmt.Sprintf("**Complexity**: %s\n", complexity))
	}

	return info.String()
}

// ============================================================================
// Built-in Documentation
// ============================================================================

// getBuiltInDocumentation returns documentation for built-in symbols
func (hp *HoverProvider) getBuiltInDocumentation(symbol string) string {
	docs := map[string]string{
		// Control Flow
		"if":   "**if-then-else**: Conditional execution\n\nSyntax: `if condition then body1 else body2 end`",
		"then": "**then**: Then branch of if statement",
		"else": "**else**: Else branch of if statement",
		"end":  "**end**: End of block (if, for, while, match)",
		"for":  "**for**: Loop over collection\n\nSyntax: `for item in collection do body end`",
		"while": "**while**: Loop while condition is true\n\nSyntax: `while condition do body end`",
		"match": "**match**: Pattern matching\n\nSyntax: `match expr case pattern -> result end`",
		"case": "**case**: Case branch in match expression",

		// Variables and Functions
		"let": "**let**: Variable declaration\n\nSyntax: `let name: Type = value` or `let name = value`",
		"function": "**function**: Function definition\n\nSyntax: `function name(params): ReturnType = body`",
		"return": "**return**: Return from function",

		// Literals and Types
		"true": "**true**: Boolean literal (true value)",
		"false": "**false**: Boolean literal (false value)",
		"Int": "**Int**: Integer type (64-bit signed)",
		"Float": "**Float**: Floating point type (64-bit)",
		"String": "**String**: String type (UTF-8 encoded)",
		"Bool": "**Bool**: Boolean type (true or false)",
		"Array": "**Array[T]**: Array type parameterized by element type",
		"Dictionary": "**Dictionary[K, V]**: Dictionary/map type",
		"Result": "**Result[T, E]**: Result type for error handling (Ok or Err)",
		"Option": "**Option[T]**: Optional type (Some or None)",
		"Unit": "**Unit**: Unit type (no return value)",

		// I/O Functions
		"println": "**println(value: String) -> Unit**\n\nPrint value with newline to stdout",
		"print": "**print(value: String) -> Unit**\n\nPrint value without newline to stdout",

		// Array Functions
		"array_map": "**array_map(arr: Array[T], fn: (T) -> U) -> Array[U]**\n\nApply function to each element\n\n*Complexity: O(n)*",
		"array_filter": "**array_filter(arr: Array[T], pred: (T) -> Bool) -> Array[T]**\n\nFilter array by predicate\n\n*Complexity: O(n)*",
		"array_fold": "**array_fold(arr: Array[T], init: U, fn: (U, T) -> U) -> U**\n\nFold/reduce array with accumulator\n\n*Complexity: O(n)*",
		"array_find": "**array_find(arr: Array[T], pred: (T) -> Bool) -> Option[T]**\n\nFind first element matching predicate\n\n*Complexity: O(n)*",
		"length": "**length(coll: Collection[T]) -> Int**\n\nGet number of elements\n\n*Complexity: O(1)*",

