		"divide": "**divide(a: Float, b: Float) -> Result[Float, String]**\n\nDivision (handles division by zero)",
		"power": "**power(base: Float, exp: Float) -> Float**\n\nExponentiation: base ^ exp\n\n*Complexity: O(log n)*",
		"abs": "**abs(x: Float) -> Float**\n\nAbsolute value",
		"sqrt": "**sqrt(x: Float) -> Float**\n\nSquare root",
		"min": "**min(a: Float, b: Float) -> Float**\n\nMinimum value",
		"max": "**max(a: Float, b: Float) -> Float**\n\nMaximum value",

		// Statistical Functions
		"sum_array": "**sum_array(arr: Array[Float]) -> Float**\n\nSum all elements\n\n*Complexity: O(n)*",
		"average": "**average(arr: Array[Float]) -> Result[Float, String]**\n\nCalculate average\n\n*Complexity: O(n)*",
		"factorial": "**factorial(n: Int) -> Result[Int, String]**\n\nCalculate n!\n\n*Complexity: O(n)*",
