// ============================================================================
// Helper Functions
// ============================================================================

// extractWord extracts the word at position
func (hp *HoverProvider) extractWord(line string, pos int) string {
	start := pos
	for start > 0 && isWordChar(rune(line[start-1])) {
		start--
	}

	end := pos
	for end < len(line) && isWordChar(rune(line[end])) {
		end++
	}

	if start < end {
		return line[start:end]
	}
	return ""
}

// extractFunctionSignature extracts function signature
func (hp *HoverProvider) extractFunctionSignature(line string) string {
	re := regexp.MustCompile(`function\s+(\w+\([^)]*\):\s*\w+)`)
	matches := re.FindStringSubmatch(line)
	if len(matches) > 1 {
		return "function " + matches[1]
	}
	return line
}

// Parameter represents a function parameter
type Parameter struct {
	Name string
	Type string
}

// extractParameters extracts function parameters
func (hp *HoverProvider) extractParameters(line string) []Parameter {
	var params []Parameter

	startIdx := strings.Index(line, "(")
	endIdx := strings.Index(line, ")")
	if startIdx < 0 || endIdx < 0 || endIdx <= startIdx {
		return params
	}

	paramStr := line[startIdx+1 : endIdx]
	for _, param := range strings.Split(paramStr, ",") {
		param = strings.TrimSpace(param)
		parts := strings.Split(param, ":")
		if len(parts) == 2 {
			params = append(params, Parameter{
				Name: strings.TrimSpace(parts[0]),
				Type: strings.TrimSpace(parts[1]),
			})
		}
	}

	return params
}

// extractReturnType extracts return type
func (hp *HoverProvider) extractReturnType(line string) string {
	re := regexp.MustCompile(`\):\s*(\w+(?:\[.*?\])?)`)
	matches := re.FindStringSubmatch(line)
	if len(matches) > 1 {
		return matches[1]
	}
	return ""
}

// analyzeComplexity analyzes time complexity
func (hp *HoverProvider) analyzeComplexity(line string) string {
	line = strings.ToLower(line)

	// Simple heuristics
	if strings.Contains(line, "map") || strings.Contains(line, "filter") {
		return "O(n)"
	}
	if strings.Contains(line, "fold") || strings.Contains(line, "reduce") {
		return "O(n)"
	}
	if strings.Contains(line, "sort") {
		return "O(n log n)"
	}
	if strings.Contains(line, "binary") || strings.Contains(line, "search") {
		return "O(log n)"
	}
	if strings.Contains(line, "fib") || strings.Contains(line, "fibonacci") {
		return "O(2^n) - consider memoization"
	}

	return ""
}

