const (
	Version = "1.0.0"
	AppName = "polyglot-pkg"
)

var (
	verboseFlag = flag.Bool("v", false, "Verbose output")
	versionFlag = flag.Bool("version", false, "Show version")
	helpFlag    = flag.Bool("h", false, "Show help")
)

// Command represents a CLI command
type Command struct {
	Name        string
	Description string
	Action      func(args []string) error
}

// CommandRegistry holds all available commands
var commands = map[string]*Command{
	"install":   {Name: "install", Description: "Install dependencies", Action: cmdInstall},
	"search":    {Name: "search", Description: "Search for packages", Action: cmdSearch},
	"update":    {Name: "update", Description: "Update dependencies", Action: cmdUpdate},
	"remove":    {Name: "remove", Description: "Remove package", Action: cmdRemove},
	"list":      {Name: "list", Description: "List installed packages", Action: cmdList},
	"info":      {Name: "info", Description: "Show package information", Action: cmdInfo},
	"package":   {Name: "package", Description: "Package current project", Action: cmdPackage},
	"publish":   {Name: "publish", Description: "Publish to registry", Action: cmdPublish},
	"verify":    {Name: "verify", Description: "Verify package integrity", Action: cmdVerify},
	"audit":     {Name: "audit", Description: "Security audit", Action: cmdAudit},
	"run":       {Name: "run", Description: "Run package script", Action: cmdRun},
	"link":      {Name: "link", Description: "Link local package", Action: cmdLink},
	"outdated":  {Name: "outdated", Description: "List outdated packages", Action: cmdOutdated},
}

// ============================================================================
// Main Entry Point
// ============================================================================

func main() {
	flag.Parse()

	if *versionFlag {
		fmt.Printf("%s version %s\n", AppName, Version)
		os.Exit(0)
	}

	if *helpFlag || flag.NArg() == 0 {
		showHelp()
		os.Exit(0)
	}

	args := flag.Args()
	cmdName := args[0]
	cmdArgs := args[1:]

	cmd, exists := commands[cmdName]
	if !exists {
		fmt.Fprintf(os.Stderr, "Error: unknown command '%s'\n", cmdName)
		showHelp()
		os.Exit(1)
	}

	if err := cmd.Action(cmdArgs); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

// showHelp displays help message
func showHelp() {
	fmt.Printf(`Polyglot Package Manager v%s

USAGE:
  %s <command> [options] [arguments]

COMMANDS:
`, Version, AppName)

	for _, cmd := range []string{
		"install", "search", "update", "remove", "list", "info",
		"package", "publish", "verify", "audit", "run", "link", "outdated",
	} {
		if c, ok := commands[cmd]; ok {
			fmt.Printf("  %-15s %s\n", cmd, c.Description)
		}
	}

	fmt.Printf(`
OPTIONS:
  -h, --help      Show this help message
  -v              Verbose output
  --version       Show version

EXAMPLES:
  # Install all dependencies
  %s install

  # Install specific package
  %s install requests

  # Search for package
  %s search json

  # List installed packages
  %s list

  # Update all dependencies
  %s update

  # Security audit
  %s audit

  # Package current project
  %s package

  # Publish to registry
  %s publish

For more information, visit: https://github.com/polyglot-poc/pkg
`, AppName, AppName, AppName, AppName, AppName, AppName, AppName, AppName)
}

// ============================================================================
// Commands Implementation
// ============================================================================

// cmdInstall installs dependencies
func cmdInstall(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if len(args) == 0 {
		// Install all from polyglot.toml
		if err := pm.ReadManifest("polyglot.toml"); err != nil {
			return fmt.Errorf("failed to read manifest: %w", err)
		}
		return pm.InstallAll()
	}

	// Install specific package
	pkgName := args[0]
	version := ""
	if len(args) > 1 {
		version = args[1]
	}

	return pm.InstallPackage(pkgName, version)
}

// cmdSearch searches for packages
func cmdSearch(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("query required")
	}

	query := args[0]
	lang := ""
	if len(args) > 1 && args[1] == "--lang" && len(args) > 2 {
		lang = args[2]
	}

	pm := NewPackageManager(*verboseFlag)
	results, err := pm.Search(query, lang)
	if err != nil {
		return err
	}

	fmt.Printf("Search results for '%s':\n\n", query)
	for _, result := range results {
		fmt.Printf("  %s@%s (%s)\n", result.Name, result.Version, result.Language)
		fmt.Printf("    Description: %s\n", result.Description)
		fmt.Printf("    Downloads: %d | Stars: %d\n", result.Downloads, result.Stars)
		fmt.Printf("\n")
	}

	return nil
}

// cmdUpdate updates dependencies
func cmdUpdate(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if len(args) == 0 {
		// Update all
		if err := pm.ReadManifest("polyglot.toml"); err != nil {
			return fmt.Errorf("failed to read manifest: %w", err)
		}
		return pm.UpdateAll()
	}

	// Update specific package
	return pm.UpdatePackage(args[0])
}

// cmdRemove removes a package
func cmdRemove(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("package name required")
	}

	pm := NewPackageManager(*verboseFlag)
	return pm.RemovePackage(args[0])
}

// cmdList lists installed packages
func cmdList(args []string) error {
	pm := NewPackageManager(*verboseFlag)
	packages, err := pm.ListInstalledPackages()
	if err != nil {
		return err
	}

	fmt.Println("Installed packages:\n")
	fmt.Printf("%-30s %-15s %-15s\n", "NAME", "VERSION", "LANGUAGE")
	fmt.Println(strings.Repeat("-", 60))

	for _, pkg := range packages {
		fmt.Printf("%-30s %-15s %-15s\n", pkg.Name, pkg.Version, pkg.Language)
	}

	fmt.Printf("\nTotal: %d packages\n", len(packages))
	return nil
}

// cmdInfo shows package information
func cmdInfo(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("package name required")
	}

	pm := NewPackageManager(*verboseFlag)
	info, err := pm.GetPackageInfo(args[0])
	if err != nil {
		return err
	}

	fmt.Printf("Package: %s\n", info.Name)
	fmt.Printf("Version: %s\n", info.Version)
	fmt.Printf("Language: %s\n", info.Language)
	fmt.Printf("Description: %s\n", info.Description)
	fmt.Printf("License: %s\n", info.License)
	fmt.Printf("Homepage: %s\n", info.Homepage)
	fmt.Printf("Repository: %s\n", info.Repository)
	fmt.Printf("Author: %s\n", info.Author)
	fmt.Printf("Downloads: %d\n", info.Downloads)
	fmt.Printf("Stars: %d\n\n", info.Stars)

	if len(info.Dependencies) > 0 {
		fmt.Println("Dependencies:")
		for _, dep := range info.Dependencies {
			fmt.Printf("  - %s@%s\n", dep.Name, dep.Version)
		}
	}

	return nil
}

// cmdPackage packages current project
func cmdPackage(args []string) error {
	pm := NewPackageManager(*verboseFlag)
	path, err := pm.PackageProject(".")
	if err != nil {
		return err
	}

	fmt.Printf("✓ Package created: %s\n", path)
	return nil
}

// cmdPublish publishes to registry
func cmdPublish(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	fmt.Println("Publishing to registry...")
	if err := pm.PublishPackage(); err != nil {
		return err
	}

	fmt.Println("✓ Package published successfully")
	return nil
}

// cmdVerify verifies package integrity
func cmdVerify(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	fmt.Println("Verifying integrity...")
	if err := pm.VerifyPackages(); err != nil {
		return err
	}

	fmt.Println("✓ All packages verified")
	return nil
}

// cmdAudit performs security audit
func cmdAudit(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	fmt.Println("Running security audit...")
	vulns, err := pm.AuditSecurity()
	if err != nil {
		return err
	}

	if len(vulns) == 0 {
		fmt.Println("✓ No vulnerabilities found")
		return nil
	}

	fmt.Printf("✗ Found %d vulnerability/vulnerabilities:\n\n", len(vulns))
	for _, vuln := range vulns {
		fmt.Printf("  Package: %s\n", vuln.Package)
		fmt.Printf("  ID: %s\n", vuln.ID)
		fmt.Printf("  Severity: %s\n", vuln.Severity)
		fmt.Printf("  Description: %s\n\n", vuln.Description)
	}

	return nil
}

// cmdRun runs package script
func cmdRun(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("script name required")
	}

	script := args[0]
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	return pm.RunScript(script)
}

// cmdLink links local package
func cmdLink(args []string) error {
	path := "."
	if len(args) > 0 {
		path = args[0]
	}

	pm := NewPackageManager(*verboseFlag)
	return pm.LinkPackage(path)
}

// cmdOutdated lists outdated packages
func cmdOutdated(args []string) error {
	pm := NewPackageManager(*verboseFlag)

	if err := pm.ReadManifest("polyglot.toml"); err != nil {
		return fmt.Errorf("failed to read manifest: %w", err)
	}

	packages, err := pm.FindOutdated()
	if err != nil {
		return err
	}

	if len(packages) == 0 {
		fmt.Println("✓ All packages are up to date")
		return nil
	}

	fmt.Printf("Outdated packages (%d):\n\n", len(packages))
	fmt.Printf("%-30s %-15s %-15s\n", "NAME", "CURRENT", "LATEST")
	fmt.Println(strings.Repeat("-", 60))

	for _, pkg := range packages {
		fmt.Printf("%-30s %-15s %-15s\n", pkg.Name, pkg.CurrentVersion, pkg.LatestVersion)
	}

	return nil
}

// ============================================================================
// Main
// ============================================================================

func init() {
	log.SetFlags(0)
}

