# 🎓 Tutorial 3: 제어 흐름 - if/else, 루프, 패턴 매칭

**난이도**: 중급 ⭐⭐⭐
**소요 시간**: 20분
**목표**: 조건문, 반복문, 패턴 매칭 학습

---

## if-else 문

### Go

```go
package main

import "fmt"

func main() {
    x := 10

    if x > 0 {
        fmt.Println("양수")
    } else if x == 0 {
        fmt.Println("0")
    } else {
        fmt.Println("음수")
    }
}
```

### C

```c
#include <stdio.h>

int main() {
    int x = 10;

    if (x > 0) {
        printf("양수\n");
    } else if (x == 0) {
        printf("0\n");
    } else {
        printf("음수\n");
    }

    return 0;
}
```

### FreeLang

```freejulia
function main(): Unit =
  let x = 10
  if x > 0 then
    println("양수")
  else if x == 0 then
    println("0")
  else
    println("음수")
  end
end
```

---

## for 루프

### Go

```go
package main

import "fmt"

func main() {
    // C 스타일
    for i := 0; i < 5; i++ {
        fmt.Printf("i = %d\n", i)
    }

    // While 스타일
    j := 0
    for j < 5 {
        fmt.Printf("j = %d\n", j)
        j++
    }

    // Range (foreach)
    arr := []int{10, 20, 30}
    for idx, val := range arr {
        fmt.Printf("[%d] = %d\n", idx, val)
    }
}
```

### C

```c
#include <stdio.h>

int main() {
    // C 스타일
    for (int i = 0; i < 5; i++) {
        printf("i = %d\n", i);
    }

    // While
    int j = 0;
    while (j < 5) {
        printf("j = %d\n", j);
        j++;
    }

    // 배열 순회
    int arr[] = {10, 20, 30};
    for (int i = 0; i < 3; i++) {
        printf("[%d] = %d\n", i, arr[i]);
    }

    return 0;
}
```

### FreeLang

```freejulia
function main(): Unit =
  # for 루프
  for i in range(0, 5) do
    println("i = " ++ string(i))
  end
end
```

---

## while 루프

### Go

```go
package main

import "fmt"

func main() {
    count := 0
    for count < 3 {  // Go에서는 while을 for로 사용
        fmt.Println("반복:", count)
        count++
    }

    // Infinite loop with break
    for {
        fmt.Println("무한 루프")
        break
    }
}
```

### C

```c
#include <stdio.h>

int main() {
    int count = 0;
    while (count < 3) {
        printf("반복: %d\n", count);
        count++;
    }

    return 0;
}
```

---

## switch 문

### Go

```go
package main

import "fmt"

func main() {
    day := 3

    switch day {
    case 1:
        fmt.Println("월요일")
    case 2:
        fmt.Println("화요일")
    case 3:
        fmt.Println("수요일")
    default:
        fmt.Println("알 수 없음")
    }
}
```

### C

```c
#include <stdio.h>

int main() {
    int day = 3;

    switch (day) {
    case 1:
        printf("월요일\n");
        break;
    case 2:
        printf("화요일\n");
        break;
    case 3:
        printf("수요일\n");
        break;
    default:
        printf("알 수 없음\n");
    }

    return 0;
}
```

