### Map 함수

```go
// Go: 배열의 각 원소에 함수 적용
func mapArray(arr []int, f func(int) int) []int {
    result := make([]int, len(arr))
    for i, v := range arr {
        result[i] = f(v)
    }
    return result
}

func main() {
    arr := []int{1, 2, 3, 4, 5}
    double := func(x int) int { return x * 2 }
    result := mapArray(arr, double)  // [2, 4, 6, 8, 10]
}
```

### Filter 함수

```go
// Go
func filterArray(arr []int, pred func(int) bool) []int {
    var result []int
    for _, v := range arr {
        if pred(v) {
            result = append(result, v)
        }
    }
    return result
}

func main() {
    arr := []int{1, 2, 3, 4, 5}
    isEven := func(x int) bool { return x%2 == 0 }
    result := filterArray(arr, isEven)  // [2, 4]
}
```

### Reduce 함수 (Fold)

```go
// Go
func reduce(arr []int, init int, op func(int, int) int) int {
    result := init
    for _, v := range arr {
        result = op(result, v)
    }
    return result
}

func main() {
    arr := []int{1, 2, 3, 4, 5}
    sum := reduce(arr, 0, func(a, b int) int {
        return a + b
    })  // 15

    product := reduce(arr, 1, func(a, b int) int {
        return a * b
    })  // 120
}
```

