import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

public class ArrayOps {

    public static int[] arrayCreate(int size, int value) {
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = value;
        }
        return arr;
    }

    public static int arraySum(int[] arr) {
        int sum = 0;
        for (int x : arr) {
            sum += x;
        }
        return sum;
    }

    public static int[] arrayMap(int[] arr, int multiplier) {
        int[] result = new int[arr.length];
        for (int i = 0; i < arr.length; i++) {
            result[i] = arr[i] * multiplier;
        }
        return result;
    }

    public static List<Integer> arrayFilter(int[] arr, int threshold) {
        List<Integer> result = new ArrayList<>();
        for (int x : arr) {
            if (x > threshold) {
                result.add(x);
            }
        }
        return result;
    }

    public static int arrayReduce(int[] arr) {
        int sum = 0;
        for (int x : arr) {
            sum += x;
        }
        return sum;
    }

    public static int[] arrayReverse(int[] arr) {
        int[] result = new int[arr.length];
        for (int i = 0; i < arr.length; i++) {
            result[i] = arr[arr.length - 1 - i];
        }
        return result;
    }

    public static int arrayFind(int[] arr, int value) {
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == value) {
                return i;
            }
        }
        return -1;
    }

    public static boolean arrayContains(int[] arr, int value) {
        for (int x : arr) {
            if (x == value) {
                return true;
            }
        }
        return false;
    }

    public static int arrayLength(int[] arr) {
        return arr.length;
    }

    public static String arrayJoin(int[] arr, String separator) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < arr.length; i++) {
            if (i > 0) {
                sb.append(separator);
            }
            sb.append(arr[i]);
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        // Create array
        int[] arr = arrayCreate(5, 1);
        System.out.println("Created array: " + java.util.Arrays.toString(arr));

        // Sum
        int total = arraySum(arr);
        System.out.println("Sum: " + total);

        // Map
