        List<Integer> filtered = arrayFilter(arr2, 2);
        System.out.println("Filtered (>2): " + filtered);

        // Reduce
        int total2 = arrayReduce(arr2);
        System.out.println("Reduce (sum): " + total2);

        // Reverse
        int[] reversedArr = arrayReverse(arr2);
        System.out.println("Reversed: " + java.util.Arrays.toString(reversedArr));

        // Find
        int idx = arrayFind(arr2, 3);
        System.out.println("Find index of 3: " + idx);

        // Contains
        boolean exists = arrayContains(arr2, 4);
        System.out.println("Contains 4: " + exists);

        // Length
        int length = arrayLength(arr2);
        System.out.println("Length: " + length);

        // Join
        String joined = arrayJoin(arr2, ",");
        System.out.println("Joined: " + joined);
    }
}

