func computeFibonacci(n int) []int {
    fib := make([]int, n)
    if n >= 1 {
        fib[0] = 0
    }
    if n >= 2 {
        fib[1] = 1
    }
    for i := 2; i < n; i++ {
        fib[i] = fib[i-1] + fib[i-2]  // O(n) 한 번만
    }
    return fib
